Here's a modern MSTest test class for `DataFetcher`:

```csharp
using System.Net;
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class DataFetcherTests
{
    // Modern MSTest natively supports async Task test methods
    [TestMethod]
    public async Task FetchAsync_ReturnsContent_OnSuccess()
    {
        var handler = new MockHttpMessageHandler("hello world", HttpStatusCode.OK);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        var result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("hello world", result);
    }

    // Use [Timeout] attribute (milliseconds) to fail slow tests
    [TestMethod]
    [Timeout(3000)]
    public async Task FetchAsync_ThrowsHttpRequestException_OnFailure()
    {
        var handler = new MockHttpMessageHandler("", HttpStatusCode.InternalServerError);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExceptionAsync<HttpRequestException>(
            () => fetcher.FetchAsync("https://example.com"));
    }

    // Test cancellation token behavior
    [TestMethod]
    public async Task FetchAsync_ThrowsOperationCanceled_WhenTokenCancelled()
    {
        var handler = new MockHttpMessageHandler("ok", HttpStatusCode.OK, delay: TimeSpan.FromSeconds(5));
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        using var cts = new CancellationTokenSource();
        cts.Cancel(); // cancel immediately

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    // Test cancellation mid-flight with a timeout source
    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_Cancels_WhenTimeoutExpires()
    {
        var handler = new MockHttpMessageHandler("ok", HttpStatusCode.OK, delay: TimeSpan.FromSeconds(30));
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        using var cts = new CancellationTokenSource(TimeSpan.FromMilliseconds(50));

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    // Minimal mock handler — no external mocking library needed
    private sealed class MockHttpMessageHandler : HttpMessageHandler
    {
        private readonly string _content;
        private readonly HttpStatusCode _statusCode;
        private readonly TimeSpan _delay;

        public MockHttpMessageHandler(string content, HttpStatusCode statusCode, TimeSpan delay = default)
        {
            _content = content;
            _statusCode = statusCode;
            _delay = delay;
        }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            if (_delay > TimeSpan.Zero)
                await Task.Delay(_delay, cancellationToken);

            return new HttpResponseMessage(_statusCode)
            {
                Content = new StringContent(_content)
            };
        }
    }
}
```

**Key patterns demonstrated:**

| Pattern | How |
|---------|-----|
| Async tests | Return `async Task` — MSTest awaits natively |
| Timeouts | `[Timeout(ms)]` attribute fails the test if it exceeds the limit |
| Cancellation | Pass a pre-cancelled or time-limited `CancellationTokenSource` |
| Exception assertions | `Assert.ThrowsExceptionAsync<T>()` for async throws |
| HttpClient mocking | Custom `HttpMessageHandler` — no external deps needed |

The `[Timeout]` attribute works cooperatively with `async Task` tests in modern MSTest (v2+). For finer-grained control, prefer `CancellationTokenSource(TimeSpan)` passed directly to your method under test.
